content.content:
1	package calibrate
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// 计划状态：进行中的计划可改期、取消或完成；已完成与已取消均为终态，
11	// 不能再改期、取消或重新开启。
12	const (
13		PlanStatusOpen     = "未完成"
14		PlanStatusDone     = "已完成"
15		PlanStatusCanceled = "已取消"
16	)
17	
18	// 待办相对本机今天的标记。
19	const (
20		TodoToday   = "今天需校准"
21		TodoOverdue = "逾期"
22		TodoFuture  = "未到计划日"
23	)
24	
25	// PlanChange 记录一次改期：保留修改前后的日期、操作时间和原因。
26	type PlanChange struct {
27		From      string `json:"from"`
28		To        string `json:"to"`
29		ChangedAt string `json:"changed_at"`
30		Reason    string `json:"reason"`
31	}
32	
33	// Plan 是一项校准计划。编号在全台账唯一，即使计划已结束编号也不再复用。
34	type Plan struct {
35		Number       string `json:"number"`
36		InstrumentID string `json:"instrument_id"`
37		// PlannedDate 是当前计划日期；OriginalDate 保留建立时的计划日期。
38		PlannedDate  string       `json:"planned_date"`
39		OriginalDate string       `json:"original_date"`
40		Note         string       `json:"note"`
41		CreatedAt    string       `json:"created_at"`
42		Changes      []PlanChange `json:"changes,omitempty"`
43		Status       string       `json:"status"`
44		// 取消时保留原计划日期、取消时间和原因。
45		CanceledAt   string `json:"canceled_at,omitempty"`
46		CancelReason string `json:"cancel_reason,omitempty"`
47		// 完成时保存完成时间和所用证书编号。
48		CompletedAt       string `json:"completed_at,omitempty"`
49		CertificateNumber string `json:"certificate_number,omitempty"`
50	}
51	
52	// Open 报告计划是否尚未结束（未完成、未取消）。
53	func (p Plan) Open() bool { return p.Status == PlanStatusOpen }
54	
55	// PlanInput 是建立校准计划的输入。
56	type PlanInput struct {
57		Number       string
58		InstrumentID string
59		Date         string
60		Note         string
61	}
62	
63	func (l *Ledger) findPlan(number string) *Plan {
64		for i := range l.data.Plans {
65			if l.data.Plans[i].Number == number {
66				return &l.data.Plans[i]
67			}
68		}
69		return nil
70	}
71	
72	// validatePlanDate 解析 YYYY-MM-DD 真实日期，且不得早于本机今天。
73	func (l *Ledger) validatePlanDate(raw, field string) (string, error) {
74		_, text, err := parseFiniteDate(raw, field)
75		if err != nil {
76			return "", err
77		}
78		todayText := l.now().Format(DateLayout)
79		if text < todayText {
80			return "", validationError("%s %s 不能早于本机今天 %s", field, text, todayText)
81		}
82		return text, nil
83	}
84	
85	// CreatePlan 为已登记器具建立一项校准计划。计划编号全台账唯一（即使对应
86	// 已结束计划也不能复用），计划日期须真实存在且不早于本机今天，说明非空；
87	// 每件器具最多有一项未完成、未取消的计划。任一条件不满足都明确拒绝，
88	// 不新增或改动任何记录。
89	func (l *Ledger) CreatePlan(in PlanInput) (*Plan, error) {
90		number, err := cleanText(in.Number)
91		if err != nil {
92			return nil, fmt.Errorf("计划编号无效：%w", err)
93		}
94		instID, err := cleanText(in.InstrumentID)
95		if err != nil {
96			return nil, fmt.Errorf("器具编号无效：%w", err)
97		}
98		note, err := cleanText(in.Note)
99		if err != nil {
100			return nil, fmt.Errorf("计划说明无效：%w", err)
101		}
102		if l.findInstrument(instID) == nil {
103			return nil, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
104		}
105		dateText, err := l.validatePlanDate(in.Date, "计划日期")
106		if err != nil {
107			return nil, err
108		}
109		if l.findPlan(number) != nil {
110			return nil, validationError("计划编号 %s 已存在，编号必须全台账唯一且不能复用", number)
111		}
112		for i := range l.data.Plans {
113			p := &l.data.Plans[i]
114			if p.InstrumentID == instID && p.Open() {
115				return nil, validationError(
116					"器具 %s 已有未结束的计划 %s（计划日期 %s），每件器具最多一项未结束计划",
117					instID, p.Number, p.PlannedDate)
118			}
119		}
120		p := Plan{
121			Number:       number,
122			InstrumentID: instID,
123			PlannedDate:  dateText,
124			OriginalDate: dateText,
125			Note:         note,
126			CreatedAt:    l.now().Format(time.RFC3339),
127			Status:       PlanStatusOpen,
128		}
129		l.data.Plans = append(l.data.Plans, p)
130		if err := l.save(); err != nil {
131			return nil, err
132		}
133		return l.findPlan(number), nil
134	}
135	
136	// requireOpenPlan 找到计划并确认其尚未结束；已结束计划返回明确的校验错误。
137	func (l *Ledger) requireOpenPlan(number string) (*Plan, error) {
138		p := l.findPlan(number)
139		if p == nil {
140			return nil, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
141		}
142		if !p.Open() {
143			return nil, validationError("计划 %s %s，已结束的计划不能再改期、取消或重新开启",
144				number, p.Status)
145		}
146		return p, nil
147	}
148	
149	// ReschedulePlan 改期一项未结束的计划。原因必须非空，新日期必须真实存在且
150	// 不早于操作当天；每次改期保留修改前后的日期、操作时间和原因。
151	// 找不到计划或计划已结束时拒绝且不改动记录。
152	//
153	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
154	// 台账（含同一对象随后的核对、计划查询与待办）与改期前完全一致——当前计划
155	// 日期不改变，失败申请的原因和时间既不进入改期历史、不改变待办标记，也不会
156	// 在此后其他成功操作写盘时被顺带写入；恢复可写后重新提交才按当时时间生效，
157	// 且只新增一条从最后成功保存的日期到新日期的记录。
158	func (l *Ledger) ReschedulePlan(number, newDate, reason string) (*Plan, error) {
159		number, err := cleanText(number)
160		if err != nil {
161			return nil, fmt.Errorf("计划编号无效：%w", err)
162		}
163		reason, err = cleanText(reason)
164		if err != nil {
165			return nil, fmt.Errorf("改期原因无效：%w", err)
166		}
167		dateText, err := l.validatePlanDate(newDate, "新计划日期")
168		if err != nil {
169			return nil, err
170		}
171		p, err := l.requireOpenPlan(number)
172		if err != nil {
173			return nil, err
174		}
175		// 即使新日期与当前日期相同也照常记录：保留修改前后的日期、操作时间和原因。
176		change := PlanChange{
177			From:      p.PlannedDate,
178			To:        dateText,
179			ChangedAt: l.now().Format(time.RFC3339),
180			Reason:    reason,
181		}
182		// 在整份计划切片的独立副本上暂存改期：只有原子替换台账文件成功后才提交。
183		// 写盘失败时恢复原切片（含原计划日期与改期历史），保证同一台账对象随后看到的
184		// 计划日期、改期历史与待办标记都与改期前一致，且不会被之后的写盘顺带写入。
185		original := l.data.Plans
186		staged := make([]Plan, len(original))
187		copy(staged, original)
188		for i := range staged {
189			if staged[i].Number != number {
190				continue
191			}
192			staged[i].Changes = append(append([]PlanChange(nil), staged[i].Changes...), change)
193			staged[i].PlannedDate = dateText
194		}
195		l.data.Plans = staged
196		if err := l.save(); err != nil {
197			l.data.Plans = original
198			return nil, err
199		}
200		return l.findPlan(number), nil
201	}
202	
203	// CancelPlan 取消一项未结束的计划，原因必须非空。取消后保留原计划、取消时间
204	// 和原因，不再列入待办，也不能重新开启。找不到计划或计划已结束时拒绝。
205	func (l *Ledger) CancelPlan(number, reason string) (*Plan, error) {
206		number, err := cleanText(number)
207		if err != nil {
208			return nil, fmt.Errorf("计划编号无效：%w", err)
209		}
210		reason, err = cleanText(reason)
211		if err != nil {
212			return nil, fmt.Errorf("取消原因无效：%w", err)
213		}
214		p, err := l.requireOpenPlan(number)
215		if err != nil {
216			return nil, err
217		}
218		p.Status = PlanStatusCanceled
219		p.CanceledAt = l.now().Format(time.RFC3339)
220		p.CancelReason = reason
221		if err := l.save(); err != nil {
222			return nil, err
223		}
224		return p, nil
225	}
226	
227	// CompletePlan 用一张台账中已有的证书完成计划。证书必须属于该器具，校准日期
228	// 不得早于计划最初建立的本机日期，且未被用于完成其他计划。符合条件后保存
229	// 完成时间和证书编号；超差证书同样表示校准工作已完成。
230	//
231	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
232	// 台账（含同一对象随后的计划查询、按器具核对与待办）与完成前完全一致——
233	// 计划仍为未完成并继续列入待办，完成时间与关联证书编号保持操作前的值，
234	// 计划日期、已有改期记录和待办日期标记都不改变，该证书也不会被算作已用于
235	// 完成计划（既不会被随后的提交当成“此前已完成”跳过保存，也不会被其他成功
236	// 写盘顺带写入文件）；恢复可写后无需重新打开台账，重新提交才真正完成，
237	// 完成时间取本次成功操作而非失败时刻。
238	//
239	// 再次用同一证书完成同一已保存为完成的计划返回原结果，不增加记录或刷新
240	// 完成时间；已完成计划改用另一证书、证书不存在或不符合条件、完成已取消
241	// 计划均拒绝。
242	func (l *Ledger) CompletePlan(number, certificateNumber string) (*Plan, bool, error) {
243		number, err := cleanText(number)
244		if err != nil {
245			return nil, false, fmt.Errorf("计划编号无效：%w", err)
246		}
247		certificateNumber, err = cleanText(certificateNumber)
248		if err != nil {
249			return nil, false, fmt.Errorf("证书编号无效：%w", err)
250		}
251		p := l.findPlan(number)
252		if p == nil {
253			return nil, false, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
254		}
255		// 幂等：同一证书再次完成同一计划，返回原结果，不刷新完成时间。
256		if p.Status == PlanStatusDone {
257			if p.CertificateNumber == certificateNumber {
258				return p, true, nil
259			}
260			return nil, false, validationError(
261				"计划 %s 已用证书 %s 完成，已完成计划不能改用另一证书",
262				number, p.CertificateNumber)
263		}
264		if p.Status == PlanStatusCanceled {
265			return nil, false, validationError("计划 %s 已取消，取消的计划不能完成；需要继续安排请建立新计划", number)
266		}
267	
268		cert := l.findCertificate(certificateNumber)
269		if cert == nil {
270			return nil, false, fmt.Errorf("证书编号 %s：%w", certificateNumber, ErrNotFound)
271		}
272		if cert.InstrumentID != p.InstrumentID {
273			return nil, false, validationError(
274				"证书 %s 属于器具 %s，不能用于完成器具 %s 的计划 %s",
275				certificateNumber, cert.InstrumentID, p.InstrumentID, number)
276		}
277		// 计划建立的本机日期：CreatedAt 是 RFC3339，取其日历日期；与证书校准日期
278		// 按日历日期比较，校准日期不得早于该日期（等于可以）。
279		created, perr := time.Parse(time.RFC3339, p.CreatedAt)
280		if perr != nil {
281			return nil, false, fmt.Errorf("计划 %s 建立时间已损坏: %w", number, perr)
282		}
283		createdDay := created.Format(DateLayout)
284		if cert.CalDate < createdDay {
285			return nil, false, validationError(
286				"证书 %s 的校准日期 %s 早于计划 %s 的建立日期 %s，不能用于完成该计划",
287				certificateNumber, cert.CalDate, number, createdDay)
288		}
289		// 同一证书不能用于完成两项计划；以幂等方式再次完成本计划已在前面处理。
290		for i := range l.data.Plans {
291			other := &l.data.Plans[i]
292			if other.Number != number && other.Status == PlanStatusDone &&
293				other.CertificateNumber == certificateNumber {
294				return nil, false, validationError(
295					"证书 %s 已用于完成计划 %s，不能再用于完成其他计划",
296					certificateNumber, other.Number)
297			}
298		}
299	
300		completedAt := l.now().Format(time.RFC3339)
301		// 在整份计划切片的独立副本上暂存完成：只有原子替换台账文件成功后才提交。
302		// 写盘失败时恢复原切片（计划仍为未完成、完成时间与关联证书编号为空），
303		// 保证同一台账对象随后看到的计划状态、待办与证书占用都与完成前一致，
304		// 再次提交不会被当成“此前已完成”，失败信息也不会被之后的写盘顺带写入。
305		original := l.data.Plans
306		staged := make([]Plan, len(original))
307		copy(staged, original)
308		for i := range staged {
309			if staged[i].Number != number {
310				continue
311			}
312			staged[i].Status = PlanStatusDone
313			staged[i].CompletedAt = completedAt
314			staged[i].CertificateNumber = certificateNumber
315		}
316		l.data.Plans = staged
317		if err := l.save(); err != nil {
318			l.data.Plans = original
319			return nil, false, err
320		}
321		return l.findPlan(number), false, nil
322	}
323	
324	// TodoItem 是待办查询中的一项计划及其按本机日期重新判断的标记。
325	type TodoItem struct {
326		PlanNumber     string `json:"plan_number"`
327		InstrumentID   string `json:"instrument_id"`
328		InstrumentName string `json:"instrument_name"`
329		Status         Status `json:"status"`
330		PlannedDate    string `json:"planned_date"`
331		Note           string `json:"note"`
332		Marker         string `json:"marker"`
333	}
334	
335	// planMarker 按计划日期相对今天给出标记：今天“今天需校准”，已过“逾期”，
336	// 未来“未到计划日”。
337	func planMarker(plannedDate, todayText string) string {
338		switch {
339		case plannedDate < todayText:
340			return TodoOverdue
341		case plannedDate == todayText:
342			return TodoToday
343		default:
344			return TodoFuture
345		}
346	}
347	
348	// Todos 列出未结束的计划作为待办。instrumentID 为空时列出全部器具的待办，
349	// 否则只列该器具（器具不存在时报 ErrNotFound）。结果按计划日期从早到晚、
350	// 同日按器具编号排列。查询不产生任何使用记录或写盘。
351	func (l *Ledger) Todos(instrumentID string) ([]TodoItem, error) {
352		id := strings.TrimSpace(instrumentID)
353		if id != "" && l.findInstrument(id) == nil {
354			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
355		}
356		todayText := l.now().Format(DateLayout)
357		items := []TodoItem{}
358		for _, p := range l.data.Plans {
359			if !p.Open() {
360				continue
361			}
362			if id != "" && p.InstrumentID != id {
363				continue
364			}
365			inst := l.findInstrument(p.InstrumentID)
366			if inst == nil {
367				continue
368			}
369			items = append(items, TodoItem{
370				PlanNumber:     p.Number,
371				InstrumentID:   inst.ID,
372				InstrumentName: inst.Name,
373				Status:         inst.Status,
374				PlannedDate:    p.PlannedDate,
375				Note:           p.Note,
376				Marker:         planMarker(p.PlannedDate, todayText),
377			})
378		}
379		sort.Slice(items, func(i, j int) bool {
380			if items[i].PlannedDate != items[j].PlannedDate {
381				return items[i].PlannedDate < items[j].PlannedDate
382			}
383			return items[i].InstrumentID < items[j].InstrumentID
384		})
385		return items, nil
386	}
387	
388	// PlanView 是计划的完整视图，供按器具核对时展示当前与已结束计划、
389	// 改期记录和关联证书编号。
390	type PlanView struct {
391		Plan
392		Marker string `json:"marker"`
393	}
394	
395	// plansOf 返回某器具的全部计划（含已结束），按建立先后排列。
396	func (l *Ledger) plansOf(id string) []Plan {
397		var out []Plan
398		for _, p := range l.data.Plans {
399			if p.InstrumentID == id {
400				out = append(out, p)
401			}
402		}
403		sort.SliceStable(out, func(i, j int) bool { return out[i].CreatedAt < out[j].CreatedAt })
404		return out
405	}
406	
407	// planViews 构造器具核对用的计划视图；标记仅对未结束计划有意义。
408	func (l *Ledger) planViews(id string, today time.Time) []PlanView {
409		todayText := today.Format(DateLayout)
410		plans := l.plansOf(id)
411		out := make([]PlanView, 0, len(plans))
412		for _, p := range plans {
413			v := PlanView{Plan: p}
414			if p.Open() {
415				v.Marker = planMarker(p.PlannedDate, todayText)
416			}
417			out = append(out, v)
418		}
419		return out
420	}
421	
422	// Plans 返回某器具的全部计划（含已结束），按建立先后排列；
423	// 器具不存在时报 ErrNotFound。
424	func (l *Ledger) Plans(instrumentID string) ([]PlanView, error) {
425		id := strings.TrimSpace(instrumentID)
426		inst := l.findInstrument(id)
427		if inst == nil {
428			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
429		}
430		return l.planViews(id, l.now()), nil
431	}
432

