4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// TestFailedRescheduleSaveLeavesNoChange 覆盖核心修复：已通过业务校验的改期在
12	// 写盘失败时明确报保存错误，计划日期、改期历史、待办标记与改期前完全一致；
13	// 恢复可写后重新提交才生效，且只记录从最后成功保存的日期出发的一条改期。
14	func TestFailedRescheduleSaveLeavesNoChange(t *testing.T) {
15		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
16		path := filepath.Join(t.TempDir(), "ledger.json")
17		l, err := openAt(path, clock.now)
18		if err != nil {
19			t.Fatalf("open: %v", err)
20		}
21		mustRegister(t, l, "M-1", "万用表", 0.5)
22		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1",
23			Date: "2026-10-10", Note: "周期校准"})
24	
25		// 第一条成功改期：10-10 → 10-20。
26		clock.t = mustDate(t, "2026-10-03")
27		first, err := l.ReschedulePlan("P-1", "2026-10-20", "实验室排期冲突")
28		if err != nil {
29			t.Fatalf("首次改期应成功: %v", err)
30		}
31		savedFirst := first.Changes[0]
32	
33		// 提交合法的第二次改期 10-20 → 11-05 时台账文件无法替换。
34		clock.t = mustDate(t, "2026-10-04")
35		blockSaving(t, l)
36		p, err := l.ReschedulePlan("P-1", "2026-11-05", "实验室改造延期")
37		if err == nil {
38			t.Fatal("台账文件无法替换时必须返回保存错误")
39		}
40		if p != nil {
41			t.Fatalf("保存失败不能返回成功的计划结果：%+v", p)
42		}
43		if IsValidation(err) || errors.Is(err, ErrNotFound) {
44			t.Fatalf("写盘失败应是保存错误而非业务拒绝：%v", err)
45		}
46	
47		// 新日期等于当前日期的改期同样只有保存成功才能留下记录。
48		if p2, err := l.ReschedulePlan("P-1", "2026-10-20", "同日重申"); err == nil || p2 != nil {
49			t.Fatalf("同日改期写盘失败也应报保存错误且不返回计划：err=%v plan=%v", err, p2)
50		}
51	
52		// 文件仍不可保存时再次提交 11-05：仍报保存失败，而不是以任何方式成功。
53		if p2, err := l.ReschedulePlan("P-1", "2026-11-05", "实验室改造延期"); err == nil || p2 != nil {
54			t.Fatalf("再次提交应仍报保存失败：err=%v plan=%v", err, p2)
55		}
56	
57		// 继续使用同一台账对象，无需重新打开：当前日期仍是最后成功保存的 10-20，
58		// 编号、所属器具、最初日期、说明和未结束状态都保留。
59		cur := l.findPlan("P-1")
60		if cur == nil {
61			t.Fatal("计划丢失")
62		}
63		if cur.PlannedDate != "2026-10-20" || cur.OriginalDate != "2026-10-10" {
64			t.Fatalf("失败改期改动了计划日期：%+v", cur)
65		}
66		if cur.Number != "P-1" || cur.InstrumentID != "M-1" ||
67			cur.Note != "周期校准" || !cur.Open() {
68			t.Fatalf("失败改期改动了计划基本信息或状态：%+v", cur)
69		}
70		// 失败申请的原因与时间不进入改期历史；第一条记录的前后日期、时间、原因及次序不变。
71		if len(cur.Changes) != 1 {
72			t.Fatalf("失败改期进入了历史，共 %d 条：%+v", len(cur.Changes), cur.Changes)
73		}
74		if cur.Changes[0] != savedFirst {
75			t.Fatalf("已成功保存的改期记录被改动：原 %+v 现 %+v", savedFirst, cur.Changes[0])
76		}
77	
78		// 待办标记按查询当天与最后成功保存的日期（10-20）判断：10-20 当天应为
79		// “今天需校准”；若误用了失败的 11-05，则会错误地显示“未到计划日”。
80		clock.t = mustDate(t, "2026-10-20")
81		items, err := l.Todos("")
82		if err != nil {
83			t.Fatalf("todos: %v", err)
84		}
85		if len(items) != 1 || items[0].PlanNumber != "P-1" ||
86			items[0].PlannedDate != "2026-10-20" || items[0].Marker != TodoToday {
87			t.Fatalf("待办应仍按 10-20 标记为今天需校准：%+v", items)
88		}
89		only, err := l.Todos("M-1")
90		if err != nil || len(only) != 1 || only[0].Marker != TodoToday {
91			t.Fatalf("按器具查待办异常：%+v err=%v", only, err)
92		}
93	
94		// 按器具核对与查询该器具计划同样使用最后成功保存的日期。
95		r, err := l.Review("M-1")
96		if err != nil {
97			t.Fatalf("review: %v", err)
98		}
99		if len(r.Plans) != 1 || r.Plans[0].PlannedDate != "2026-10-20" ||
100			r.Plans[0].Marker != TodoToday || len(r.Plans[0].Changes) != 1 {
101			t.Fatalf("核对结果应与失败前一致：%+v", r.Plans)
102		}
103		views, err := l.Plans("M-1")
104		if err != nil || len(views) != 1 || views[0].PlannedDate != "2026-10-20" ||
105			len(views[0].Changes) != 1 {
106			t.Fatalf("计划查询应与失败前一致：%+v err=%v", views, err)
107		}
108	
109		// 恢复文件可写后不必重开台账：先做一次与改期无关、能够成功保存的正常操作
110		// （顺带停用器具），失败的改期不能被顺带写入文件。
111		restoreSaving(t, l)
112		if err := l.SetStatus("M-1", StatusRetired); err != nil {
113			t.Fatalf("恢复后正常操作应能保存: %v", err)
114		}
115		raw, err := os.ReadFile(path)
116		if err != nil {
117			t.Fatalf("读取台账文件: %v", err)
118		}
119		if strings.Contains(string(raw), "2026-11-05") || strings.Contains(string(raw), "实验室改造延期") {
120			t.Fatalf("失败改期被随后成功的写盘顺带写入文件：\n%s", raw)
121		}
122		reopened, err := openAt(path, clock.now)
123		if err != nil {
124			t.Fatalf("reopen: %v", err)
125		}
126		rp := reopened.findPlan("P-1")
127		if rp == nil || rp.PlannedDate != "2026-10-20" || len(rp.Changes) != 1 {
128			t.Fatalf("文件中的计划应停留在最后成功保存的状态：%+v", rp)
129		}
130	
131		// 停用器具的计划仍可改期：在同一台账对象重新提交合法改期到 11-08。
132		// 当前日期才改为 11-08，且只新增一条 10-20 → 11-08，时间取本次成功操作；
133		// 历史保留第一条，任何位置都不能出现 11-05。
134		clock.t = mustDate(t, "2026-10-21")
135		ok, err := l.ReschedulePlan("P-1", "2026-11-08", "改造完成重新排期")
136		if err != nil || ok == nil {
137			t.Fatalf("恢复后重新提交应成功：err=%v plan=%v", err, ok)
138		}
139		if ok.PlannedDate != "2026-11-08" || ok.Status != PlanStatusOpen {
140			t.Fatalf("成功后当前计划日期才应改变：%+v", ok)
141		}
142		inst := l.findInstrument("M-1")
143		if inst == nil || inst.Status != StatusRetired {
144			t.Fatalf("改期不应改变器具状态：%+v", inst)
145		}
146		if len(ok.Changes) != 2 {
147			t.Fatalf("应只有两条改期记录，得到 %d：%+v", len(ok.Changes), ok.Changes)
148		}
149		if ok.Changes[0] != savedFirst {
150			t.Fatalf("第一条改期记录不能变化：原 %+v 现 %+v", savedFirst, ok.Changes[0])
151		}
152		second := ok.Changes[1]
153		wantSecond := PlanChange{
154			From:      "2026-10-20",
155			To:        "2026-11-08",
156			Reason:    "改造完成重新排期",
157			ChangedAt: "2026-10-21T00:00:00Z",
158		}
159		if second != wantSecond {
160			t.Fatalf("新增记录应为最后成功日期 10-20 到 11-08、采用本次操作时间：%+v", second)
161		}
162	
163		// 重新打开文件：磁盘上同样只有两条记录且无 11-05。
164		reopened, err = openAt(path, clock.now)
165		if err != nil {
166			t.Fatalf("reopen: %v", err)
167		}
168		rp = reopened.findPlan("P-1")
169		if rp == nil || rp.PlannedDate != "2026-11-08" || len(rp.Changes) != 2 {
170			t.Fatalf("重开后计划状态异常：%+v", rp)
171		}
172		if rp.Changes[0] != savedFirst || rp.Changes[1] != wantSecond {
173			t.Fatalf("重开后改期历史异常：%+v", rp.Changes)
174		}
175		raw, err = os.ReadFile(path)
176		if err != nil {
177			t.Fatalf("读取台账文件: %v", err)
178		}
179		if strings.Contains(string(raw), "2026-11-05") {
180			t.Fatalf("失败日期 11-05 被写入文件：\n%s", raw)
181		}
182	}
183	
184	// TestRescheduleValidationRejectedWhileSavingBlocked 区分文件读写错误与业务
185	// 拒绝：文件不可写时，日期或原因不符合要求仍按业务校验拒绝（返回校验错误），
186	// 且不进行写盘尝试、不改动任何记录。
187	func TestRescheduleValidationRejectedWhileSavingBlocked(t *testing.T) {
188		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
189		path := filepath.Join(t.TempDir(), "ledger.json")
190		l, err := openAt(path, clock.now)
191		if err != nil {
192			t.Fatalf("open: %v", err)
193		}
194		mustRegister(t, l, "M-1", "万用表", 0.5)
195		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-10", Note: "周期"})
196	
197		blockSaving(t, l)
198		bad := []struct {
199			name    string
200			date    string
201			reason  string
202			num     string
203			wantVal bool
204		}{
205			{"空白原因", "2026-11-05", "  ", "P-1", true},
206			{"早于操作当天", "2026-10-01", "提前", "P-1", true},
207			{"不存在的日期", "2026-11-31", "x", "P-1", true},
208			{"未知计划", "2026-11-05", "x", "NOPE", false},
209		}
210		for _, tc := range bad {
211			t.Run(tc.name, func(t *testing.T) {
212				p, err := l.ReschedulePlan(tc.num, tc.date, tc.reason)
213				if err == nil {
214					t.Fatalf("用例 %q 应被拒绝", tc.name)
215				}
216				if p != nil {
217					t.Fatalf("业务拒绝不能返回计划结果：%+v", p)
218				}
219				if tc.wantVal && !IsValidation(err) {
220					t.Fatalf("用例 %q 应是业务校验错误而非文件错误：%v", tc.name, err)
221				}
222				if !tc.wantVal && !errors.Is(err, ErrNotFound) {
223					t.Fatalf("未知计划应报 ErrNotFound：%v", err)
224				}
225			})
226		}
227		got := l.findPlan("P-1")
228		if got.PlannedDate != "2026-10-10" || len(got.Changes) != 0 || !got.Open() {
229			t.Fatalf("业务拒绝后计划被改动：%+v", got)
230		}
231	}
