1	package main
2	
3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// rescheduleArgs 构造一条计划改期命令。
12	func rescheduleArgs(path, number, date, reason string) []string {
13		return []string{"reschedule", "-f", path,
14			"--number", number, "--date", date, "--reason", reason}
15	}
16	
17	// planArgs 构造一条建立校准计划命令（日期取较远的未来，避免依赖运行当天）。
18	func planArgs(path, instrument, number, date string) []string {
19		return []string{"plan", "-f", path,
20			"--instrument", instrument, "--number", number,
21			"--date", date, "--note", "周期校准"}
22	}
23	
24	// TestRescheduleSaveFailureIsFileErrorAndRecoverable 验证命令行改期在台账文件
25	// 无法写入时按文件读写错误报告、退出码 2、不显示“已改期”；失败后无需重开台账，
26	// 核对、计划查询与待办仍使用最后成功保存的日期，失败日期不进文件、不被此后的
27	// 成功写盘夹带。恢复可写后重新提交才生效，只新增一条从最后成功日期出发的记录。
28	func TestRescheduleSaveFailureIsFileErrorAndRecoverable(t *testing.T) {
29		dir := chdirTemp(t)
30		// 台账放在子目录里：把子目录改成只读即可挡住写临时文件与改名替换，
31		// 已存在的台账文件本身仍可读，查询不受影响。
32		sub := filepath.Join(dir, "只读目录")
33		if err := os.Mkdir(sub, 0o755); err != nil {
34			t.Fatal(err)
35		}
36		target := filepath.Join(sub, "ledger.json")
37		if r := runArgs(t, registerArgs(target, "M-1")...); r.code != 0 {
38			t.Fatalf("登记器具失败 code=%d stderr=%s", r.code, r.stderr)
39		}
40		if r := runArgs(t, planArgs(target, "M-1", "P-1", "2030-10-10")...); r.code != 0 {
41			t.Fatalf("建立计划失败 code=%d stderr=%s", r.code, r.stderr)
42		}
43		// 第一条成功改期：10-10 → 10-20。
44		if r := runArgs(t, rescheduleArgs(target, "P-1", "2030-10-20", "实验室排期冲突")...); r.code != 0 {
45			t.Fatalf("首次改期应成功 code=%d stderr=%s", r.code, r.stderr)
46		}
47	
48		// 目录只读：save 无法创建临时文件；测试结束后恢复权限便于清理。
49		if err := os.Chmod(sub, 0o555); err != nil {
50			t.Fatal(err)
51		}
