1	package calibrate
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	func mustPlan(t *testing.T, l *Ledger, in PlanInput) *Plan {
14		t.Helper()
15		p, err := l.CreatePlan(in)
16		if err != nil {
17			t.Fatalf("create plan %s: %v", in.Number, err)
18		}
19		return p
20	}
21	
22	func TestCreatePlanValidation(t *testing.T) {
23		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
24		l := newTestLedger(t, clock)
25		mustRegister(t, l, "M-1", "万用表", 0.5)
26	
27		base := PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-10", Note: "周期校准"}
28		valid := func(mut func(*PlanInput)) PlanInput {
29			p := base
30			mut(&p)
31			return p
32		}
33		bad := []struct {
34			name     string
35			in       PlanInput
36			notFound bool
37		}{
38			{"未知器具", valid(func(p *PlanInput) { p.InstrumentID = "X-9" }), true},
39			{"空白计划编号", valid(func(p *PlanInput) { p.Number = "  " }), false},
40			{"空白器具编号", valid(func(p *PlanInput) { p.InstrumentID = "\t" }), false},
41			{"空白说明", valid(func(p *PlanInput) { p.Note = "" }), false},
42			{"不存在的日期2月30日", valid(func(p *PlanInput) { p.Date = "2026-02-30" }), false},
43			{"不存在的月份13月", valid(func(p *PlanInput) { p.Date = "2026-13-01" }), false},
44			{"格式不符", valid(func(p *PlanInput) { p.Date = "2026-10-1" }), false},
45			{"日期早于今天", valid(func(p *PlanInput) { p.Date = "2026-10-01" }), false},
46		}
47		for _, tc := range bad {
48			t.Run(tc.name, func(t *testing.T) {
49				n := len(l.data.Plans)
50				_, err := l.CreatePlan(tc.in)
51				if err == nil {
52					t.Fatalf("用例 %q 应被拒绝", tc.name)
53				}
54				if tc.notFound {
55					if !errors.Is(err, ErrNotFound) {
56						t.Fatalf("未知器具应报 ErrNotFound，得到 %v", err)
57					}
58				} else if !IsValidation(err) {
59					t.Fatalf("用例 %q 应报校验错误，得到 %v", tc.name, err)
60				}
61				if len(l.data.Plans) != n {
62					t.Fatalf("用例 %q 留下了计划记录", tc.name)
63				}
64			})
65		}
66	
67		// 计划日期等于本机今天允许。
68		p := mustPlan(t, l, PlanInput{Number: "P-ok", InstrumentID: "M-1", Date: "2026-10-02", Note: "今天"})
69		if p.OriginalDate != "2026-10-02" || p.Status != PlanStatusOpen {
70			t.Fatalf("新计划字段异常：%+v", p)
71		}
72	
73		// 每件器具最多一项未结束计划。
74		if _, err := l.CreatePlan(PlanInput{Number: "P-2", InstrumentID: "M-1", Date: "2026-11-01", Note: "二"}); !IsValidation(err) {
75			t.Fatalf("同器具第二项未结束计划应拒绝，得到 %v", err)
76		}
77		if l.findPlan("P-2") != nil {
78			t.Fatal("被拒绝的计划不应存在")
79		}
80	}
81	
82	func TestPlanNumberUniqueAndNotReused(t *testing.T) {
83		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
84		l := newTestLedger(t, clock)
85		mustRegister(t, l, "M-1", "万用表", 0.5)
86		mustRegister(t, l, "M-2", "示波器", 1.0)
87	
88		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-10", Note: "一"})
89		// 进行中编号不能被别的器具复用。
90		if _, err := l.CreatePlan(PlanInput{Number: "P-1", InstrumentID: "M-2", Date: "2026-10-10", Note: "占用"}); !IsValidation(err) {
91			t.Fatalf("进行中的编号应拒绝复用，得到 %v", err)
92		}
93	
94		mustAddCert(t, l, CertificateInput{
95			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-10-02",
96			Expiry: "2027-10-02", Method: "m", Error: 0.1, Summary: "s",
97		})
98		if _, _, err := l.CompletePlan("P-1", "C-1"); err != nil {
99			t.Fatalf("complete: %v", err)
100		}
101		// 编号即使对应已完成计划也不能复用（即使换器具）。
102		if _, err := l.CreatePlan(PlanInput{Number: "P-1", InstrumentID: "M-2", Date: "2026-10-10", Note: "复用"}); !IsValidation(err) {
103			t.Fatalf("已结束计划编号应拒绝复用，得到 %v", err)
104		}
105	
106		// 取消的计划编号同样不能复用；但原器具可以另建新计划。
107		mustPlan(t, l, PlanInput{Number: "P-2", InstrumentID: "M-2", Date: "2026-10-11", Note: "二"})
108		if _, err := l.CancelPlan("P-2", "暂停送检"); err != nil {
109			t.Fatalf("cancel: %v", err)
110		}
111		if _, err := l.CreatePlan(PlanInput{Number: "P-2", InstrumentID: "M-2", Date: "2026-10-12", Note: "复用"}); !IsValidation(err) {
112			t.Fatalf("已取消计划编号应拒绝复用，得到 %v", err)
113		}
114		mustPlan(t, l, PlanInput{Number: "P-3", InstrumentID: "M-2", Date: "2026-10-12", Note: "重新安排"})
115	}
116	
117	func TestRescheduleRecordsHistory(t *testing.T) {
118		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
119		l := newTestLedger(t, clock)
120		mustRegister(t, l, "M-1", "万用表", 0.5)
121		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-10", Note: "周期"})
122	
123		// 未知计划拒绝且不改动。
124		if _, err := l.ReschedulePlan("NOPE", "2026-10-20", "原因"); !errors.Is(err, ErrNotFound) {
125			t.Fatalf("未知计划应报 ErrNotFound，得到 %v", err)
126		}
127		// 空白原因、过去日期、相同日期都拒绝。
128		if _, err := l.ReschedulePlan("P-1", "2026-10-20", "  "); !IsValidation(err) {
129			t.Fatalf("空白原因应拒绝，得到 %v", err)
130		}
131		if _, err := l.ReschedulePlan("P-1", "2026-10-01", "提前"); !IsValidation(err) {
132			t.Fatalf("早于操作当天的日期应拒绝，得到 %v", err)
133		}
134		if got := l.findPlan("P-1"); len(got.Changes) != 0 || got.PlannedDate != "2026-10-10" {
135			t.Fatalf("失败的改期改动了记录：%+v", got)
136		}
137	
138		// 合法改期：保留修改前后日期、操作时间和原因；最初日期不变。
139		clock.t = mustDate(t, "2026-10-03")
140		p2, err := l.ReschedulePlan("P-1", "2026-10-20", "实验室排期冲突")
141		if err != nil {
142			t.Fatalf("reschedule: %v", err)
143		}
144		if p2.PlannedDate != "2026-10-20" || p2.OriginalDate != "2026-10-10" {
145			t.Fatalf("改期后日期字段异常：%+v", p2)
146		}
147		if len(p2.Changes) != 1 || p2.Changes[0].From != "2026-10-10" ||
148			p2.Changes[0].To != "2026-10-20" || p2.Changes[0].Reason != "实验室排期冲突" ||
149			p2.Changes[0].ChangedAt == "" {
150			t.Fatalf("改期记录不完整：%+v", p2.Changes)
151		}
152	}
153	
154	func TestEndedPlansCannotChange(t *testing.T) {
155		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
156		l := newTestLedger(t, clock)
157		mustRegister(t, l, "M-1", "万用表", 0.5)
158		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-10", Note: "一"})
159	
160		if _, err := l.CancelPlan("P-1", "停产"); err != nil {
161			t.Fatalf("cancel: %v", err)
162		}
163		// 已取消：不能再改期、取消或重新开启。
164		for _, act := range []func() error{
165			func() error { _, e := l.ReschedulePlan("P-1", "2026-10-20", "x"); return e },
166			func() error { _, e := l.CancelPlan("P-1", "x"); return e },
167		} {
168			if err := act(); !IsValidation(err) {
169				t.Fatalf("已取消计划再操作应拒绝，得到 %v", err)
170			}
