	// 保持空白；当前计划日期、最初计划日期、说明与已有改期记录都不改变。
	cur := l.findPlan("P-1")
	if cur == nil {
		t.Fatal("计划丢失")
	}
	if !cur.Open() || cur.CanceledAt != "" || cur.CancelReason != "" {
		t.Fatalf("失败取消改动了取消信息：%+v", cur)
	}
