	}
	// 失败申请的时间与原因不能出现在任何位置（这里直接检查内存中的整个计划）。
	if cur.CanceledAt != "" || strings.Contains(cur.CancelReason, failedReason) {
		t.Fatalf("失败申请的时间或原因留了下来：%+v", cur)
	}

