	r, err := l.Review("M-1")
	if err != nil {
		t.Fatalf("review: %v", err)
	}
	if len(r.Plans) != 1 || r.Plans[0].Status != PlanStatusOpen ||
		r.Plans[0].Marker != TodoToday ||
		r.Plans[0].CanceledAt != "" || r.Plans[0].CancelReason != "" ||
		len(r.Plans[0].Changes) != 1 {
		t.Fatalf("核对结果应与失败前一致：%+v", r.Plans)
	}
