	if err != nil || len(views) != 1 || views[0].Status != PlanStatusOpen ||
		views[0].CanceledAt != "" || views[0].CancelReason != "" {
		t.Fatalf("计划查询应与失败前一致：%+v err=%v", views, err)
	}

